-- 0001_initial_schema.sql
-- Forward-only migration. Never edit after it has been applied anywhere; add 0002_*.sql instead.
-- Uses the SQL subset accepted by both SQLite and PostgreSQL:
--   ids are TEXT (generated by the application), times are BIGINT UTC epoch milliseconds,
--   structured values are JSON stored as TEXT.

CREATE TABLE streams (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    source_uri      TEXT NOT NULL,           -- may contain ${ENV} references, never plaintext secrets
    enabled         INTEGER NOT NULL DEFAULT 1,
    created_at_ms   BIGINT NOT NULL,
    updated_at_ms   BIGINT NOT NULL
);

CREATE TABLE zones (
    stream_id       TEXT NOT NULL REFERENCES streams (id) ON DELETE CASCADE,
    id              TEXT NOT NULL,
    name            TEXT NOT NULL,
    polygon_json    TEXT NOT NULL,           -- [[x, y], ...] normalized [0, 1]
    updated_at_ms   BIGINT NOT NULL,
    PRIMARY KEY (stream_id, id)
);

CREATE TABLE gates (
    stream_id       TEXT NOT NULL REFERENCES streams (id) ON DELETE CASCADE,
    id              TEXT NOT NULL,
    name            TEXT NOT NULL,
    line_json       TEXT NOT NULL,           -- [[x1, y1], [x2, y2]] normalized [0, 1]
    updated_at_ms   BIGINT NOT NULL,
    PRIMARY KEY (stream_id, id)
);

CREATE TABLE solutions (
    stream_id       TEXT NOT NULL REFERENCES streams (id) ON DELETE CASCADE,
    position        INTEGER NOT NULL,        -- execution order within the stream
    type            TEXT NOT NULL,           -- e.g. zone_intrusion
    params_json     TEXT NOT NULL DEFAULT '{}',
    PRIMARY KEY (stream_id, position)
);

CREATE TABLE events (
    id              TEXT PRIMARY KEY,
    stream_id       TEXT NOT NULL,
    type            TEXT NOT NULL,           -- <solution_type>.<event_name>
    occurred_at_ms  BIGINT NOT NULL,
    frame_sequence  BIGINT NOT NULL,
    track_id        BIGINT,
    zone_id         TEXT,
    gate_id         TEXT,
    attributes_json TEXT NOT NULL DEFAULT '{}',
    snapshot_path   TEXT                     -- relative to storage.media_dir
);

CREATE INDEX idx_events_stream_time ON events (stream_id, occurred_at_ms);
CREATE INDEX idx_events_type_time ON events (type, occurred_at_ms);
